// The "scavenger" player character (public/models/scavenger.glb, generated by tools/models/scavenger.py).
//
//   const model = new ScavengerModel(0xff8844);   // root is empty until the glb has loaded
//   scene.add(model.root);
//   model.update({ speed, grounded, digging, sliding, pitch }, dt);  // every render frame
//
// The root faces -Z (same as the placeholder avatar: facing 0 looks down -Z) with its origin at the feet.
// The glb is fetched once and shared; each instance gets its own skeleton (SkeletonUtils.clone) and its
// own copy of the `PlayerTint` material (scarf, face mask, sash, armband), which setColor() recolours.
import * as THREE from 'three/webgpu';
import { GLTFLoader, type GLTF } from 'three/addons/loaders/GLTFLoader.js';
import { clone as cloneSkinned } from 'three/addons/utils/SkeletonUtils.js';
import { LegIk, lowestAnkles, type Ground } from './legIk';
import type { RidePose } from '../players';
import type { Held } from '../water';

export type ScavengerPose = {
  /** Horizontal speed in m/s. */
  speed: number;
  grounded: boolean;
  digging?: boolean;
  /** Slipping down a slip face (clip 'Slide'). */
  sliding?: boolean;
  /** Intentional Ctrl slide (clip 'Powerslide'); the body tilts to the ground by tiltPitch / tiltRoll
   *  (rad; + pitch = uphill ahead, + roll = uphill to the right). */
  powerSlide?: boolean;
  /** Crouched ('Crouch' standing, 'CrouchWalk' moving). */
  crouching?: boolean;
  tiltPitch?: number;
  tiltRoll?: number;
  /** Look pitch in radians (+ = up); tilts neck and head. */
  pitch?: number;
  /** Direction of travel relative to facing (rad): 0 ahead, +π/2 right, ±π backwards. Turns the hips
   *  toward it (the torso keeps facing ahead) and plays the stride in reverse when backing up. */
  heading?: number;
  /** Sand height sampler for foot placement; omit when not standing on sand (flat feet). */
  ground?: Ground;
  /** Pin planted feet to the world (default true). Off for a model animating in place, e.g. the lab. */
  plant?: boolean;
  /** Seated on a bike: hips on the seat, hands on the grips and feet on the pegs by IK, over the Idle clip. */
  ride?: RidePose;
  /** What's in the right hand (the canteen, public/models/canteen.glb): carried in front at the waist. */
  held?: Held;
  /** Drinking from the canteen: raised to the mouth and tipped up. */
  drinking?: boolean;
};

export type ScavengerClip = 'Idle' | 'Walk' | 'Run' | 'Jump' | 'Dig' | 'Slide' | 'Powerslide' | 'Crouch' | 'CrouchWalk';

const URL = './models/scavenger.glb';
const FADE = 0.2;
// Ground speed (m/s) at which each locomotion clip plays at timeScale 1 without the feet sliding.
const WALK_REF = 1.3;
const RUN_REF = 4.7;
const CROUCH_REF = 1.0;
const RUN_ABOVE = 2.8;
const MAX_HIP_YAW = 1.0; // rad; strafing beyond this shows as a crab-walk rather than hips turned further

const CANTEEN_URL = './models/canteen.glb';
/** Carried canteen, root space (forward -Z, right +X): where its bottom sits and its forward tip (rad). */
const CARRY_AT = new THREE.Vector3(0.32, 0.88, -0.2);
const CARRY_TIP = -0.15;
/** Drinking: tipped back, neck at the mouth (head-bone space, glTF: face +Z). */
const DRINK_TIP = 1.9;
const MOUTH = new THREE.Vector3(0, 0.02, 0.13);
const CANTEEN_HEIGHT = 0.21;
/** Where the fist grips it, up from the bottom. */
const GRIP_UP = 0.1;

let cached: Promise<GLTF> | null = null;
let canteenCached: Promise<GLTF> | null = null;
const ANKLES = ['LeftFoot', 'RightFoot'];
const lowest = new WeakMap<GLTF, Map<string, number>>();

/** Starts (or reuses) the glb download. Call early to warm the cache. */
export function loadScavenger(): Promise<GLTF> {
  cached ??= new GLTFLoader().loadAsync(URL);
  return cached;
}

export class ScavengerModel {
  /** Add this to the scene and position/rotate it like the placeholder avatar. */
  readonly root = new THREE.Group();
  /** Between root and model: leans the whole body to the slope while power-sliding. */
  private tilt = new THREE.Group();
  /** Resolves once the model is in `root` and animating. */
  readonly ready: Promise<void>;

  private mixer: THREE.AnimationMixer | null = null;
  private actions = new Map<string, THREE.AnimationAction>();
  private current: THREE.AnimationAction | null = null;
  private tint: THREE.MeshStandardMaterial[] = [];
  private neck: THREE.Object3D | null = null;
  private head: THREE.Object3D | null = null;
  private legIk: LegIk | null = null;
  private minAnkle = new Map<string, number>();
  /** Bones adjusted after the mixer, with their animated rotation (see update()). */
  private posed: { bone: THREE.Object3D; base: THREE.Quaternion }[] = [];
  private speed = 0;
  private backwards = false;
  private hipYaw = 0;
  private hips: THREE.Object3D | null = null;
  private spine: THREE.Object3D | null = null;
  /** Upper arm, forearm, hand, index finger (left, right). */
  private arms: THREE.Object3D[][] = [];
  /** Thigh, shin, foot, toes (left, right). */
  private legs: THREE.Object3D[][] = [];
  private headless = false;
  private canteen: THREE.Object3D | null = null;
  private held: Held = 'none';
  private sip = 0; // 0 carried .. 1 at the mouth
  private color: number;
  private disposed = false;

  constructor(color = 0xffffff) {
    this.color = color;
    this.root.name = 'Scavenger';
    this.root.add(this.tilt);
    this.ready = loadScavenger().then((gltf) => this.init(gltf));
  }

  private init(gltf: GLTF) {
    if (this.disposed) return;
    const model = cloneSkinned(gltf.scene);
    model.rotation.y = Math.PI; // glTF character faces +Z; the game's "forward" is -Z
    model.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (!mesh.isMesh) return;
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      mesh.frustumCulled = false; // skinned bounds don't follow the animation
      const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      const own = mats.map((m) => {
        if (m.name !== 'PlayerTint') return m;
        const c = (m as THREE.MeshStandardMaterial).clone();
        this.tint.push(c);
        return c;
      });
      mesh.material = Array.isArray(mesh.material) ? own : own[0];
    });
    this.neck = model.getObjectByName('Neck') ?? null;
    this.head = model.getObjectByName('Head') ?? null;
    const bone = (n: string) => model.getObjectByName(n);
    const legs = ['Left', 'Right'].map((s) => [bone(`${s}UpLeg`), bone(`${s}Leg`), bone(`${s}Foot`)]);
    if (legs.every((l) => l.every((b) => b))) {
      this.legIk = new LegIk(this.root, model, legs as [THREE.Object3D, THREE.Object3D, THREE.Object3D][]);
    }
    if (!lowest.has(gltf)) lowest.set(gltf, lowestAnkles(gltf.scene, gltf.animations, ANKLES));
    this.minAnkle = lowest.get(gltf)!;
    this.hips = bone('Hips') ?? null;
    this.spine = bone('Spine') ?? null;
    const chain = (names: string[]) => names.map(bone).filter((b) => b !== undefined);
    const arms = ['Left', 'Right'].map((s) => chain([`${s}Arm`, `${s}ForeArm`, `${s}Hand`, `${s}HandIndex1`]));
    const feet = ['Left', 'Right'].map((s) => chain([`${s}UpLeg`, `${s}Leg`, `${s}Foot`, `${s}ToeBase`]));
    if (arms.every((a) => a.length === 4)) this.arms = arms;
    if (feet.every((l) => l.length === 4)) this.legs = feet;
    for (const b of [this.neck, this.head, this.hips, this.spine, ...legs.flat(), ...this.arms.flat(), ...this.legs.flat()]) {
      if (b && !this.posed.some((p) => p.bone === b)) this.posed.push({ bone: b, base: b.quaternion.clone() });
    }
    this.mixer = new THREE.AnimationMixer(model);
    for (const clip of gltf.animations) this.actions.set(clip.name, this.mixer.clipAction(clip));
    this.tilt.add(model);
    this.setColor(this.color);
    this.play('Idle', 0);
    // The canteen lives in the root (not the hand bone), placed each frame; the right arm reaches for it.
    canteenCached ??= new GLTFLoader().loadAsync(CANTEEN_URL);
    canteenCached.then((c) => {
      if (this.disposed) return;
      const can = c.scene.clone();
      can.traverse((o) => {
        if ((o as THREE.Mesh).isMesh) o.castShadow = o.receiveShadow = true;
      });
      can.visible = false;
      this.root.add(can);
      this.canteen = can;
    }, (e) => console.warn('canteen model failed to load', e));
  }

  setColor(hex: number) {
    this.color = hex;
    for (const m of this.tint) m.color.setHex(hex);
  }

  setHeadless(on: boolean) {
    this.headless = on;
  }

  /** The eyes' world position (between them, a little forward of the head bone), once loaded. */
  eye(out: THREE.Vector3): boolean {
    if (!this.head) return false;
    out.set(0, 0.09, 0.08).applyMatrix4(this.head.matrixWorld); // glTF space: the face is +Z
    return true;
  }

  /** Clip names available once loaded. */
  get clips(): string[] {
    return [...this.actions.keys()];
  }

  /** Force a clip (used by the lab page); update() picks clips automatically from the pose. */
  play(name: ScavengerClip | string, fade = FADE, timeScale = 1) {
    const next = this.actions.get(name);
    if (!next) return;
    next.timeScale = timeScale;
    if (next === this.current) return;
    const prev = this.current;
    next.enabled = true;
    next.setEffectiveWeight(1);
    if (prev && isLocomotion(prev) && isLocomotion(next)) {
      // keep the foot phase when switching between walk and run
      next.time = (prev.time / prev.getClip().duration) * next.getClip().duration;
    } else {
      next.time = 0;
    }
    next.play();
    if (prev && fade > 0) prev.crossFadeTo(next, fade, false);
    else if (prev) prev.stop();
    this.current = next;
  }

  /** Called every render frame. */
  update(pose: ScavengerPose, dt: number) {
    this.held = pose.held ?? 'none';
    if (!this.mixer) return;
    // Remote speeds arrive as 20 Hz steps; smooth them so playback rate (and the feet) don't jitter.
    this.speed += (pose.speed - this.speed) * (1 - Math.exp(-dt * 10));
    const speed = this.speed;
    // Backing up plays the stride in reverse; the hips turn toward the travel direction (or away from it
    // when backing up) so diagonal and sideways moves step that way instead of moonwalking.
    const heading = pose.heading ?? 0;
    const moving = !pose.ride && pose.grounded && !pose.sliding && !pose.powerSlide && !pose.digging && speed > 0.25;
    if (moving) {
      const ahead = Math.cos(heading);
      if (ahead < -0.25) this.backwards = true;
      else if (ahead > 0.1) this.backwards = false;
    }
    const legDir = this.backwards ? Math.atan2(-Math.sin(heading), -Math.cos(heading)) : heading;
    const hipTarget = moving ? clamp(legDir, -MAX_HIP_YAW, MAX_HIP_YAW) : 0;
    this.hipYaw += (hipTarget - this.hipYaw) * (1 - Math.exp(-dt * 8));
    const dir = this.backwards ? -1 : 1;
    if (pose.ride) this.play('Idle');
    else if (!pose.grounded) this.play('Jump');
    else if (pose.powerSlide) this.play('Powerslide', 0.12);
    else if (pose.sliding) this.play('Slide');
    else if (pose.digging) this.play('Dig');
    else if (pose.crouching && speed > 0.25) this.play('CrouchWalk', FADE, dir * clamp(speed / CROUCH_REF, 0.6, 2.2));
    else if (pose.crouching) this.play('Crouch');
    else if (speed > RUN_ABOVE) this.play('Run', FADE, dir * clamp(speed / RUN_REF, 0.75, 1.6));
    else if (speed > 0.25) this.play('Walk', FADE, dir * clamp(speed / WALK_REF, 0.6, 1.8));
    else this.play('Idle');
    // The mixer only writes a bone when its animated value changes, so on a constant track (Dig's Neck,
    // its kneeling legs) last frame's look tilt / IK would stay in place and pile up. Undo them first.
    for (const p of this.posed) p.bone.quaternion.copy(p.base);
    this.mixer.update(dt);
    // Lean to the slope: pitch about the model's X (+ = nose up), roll about Z, pivoting at the feet.
    const tk = 1 - Math.exp(-dt * 10);
    const power = !!pose.powerSlide && pose.grounded && !pose.ride;
    this.tilt.position.set(0, 0, 0);
    this.tilt.rotation.x += ((power ? clamp(pose.tiltPitch ?? 0, -0.9, 0.9) : 0) - this.tilt.rotation.x) * tk;
    this.tilt.rotation.z += ((power ? clamp(pose.tiltRoll ?? 0, -0.9, 0.9) : 0) - this.tilt.rotation.z) * tk;
    for (const p of this.posed) p.base.copy(p.bone.quaternion);

    this.root.updateMatrixWorld(true);
    if (Math.abs(this.hipYaw) > 1e-3 && this.hips && this.spine) {
      // +heading is to the right, which is a negative turn about +Y; the spine turns back to face ahead.
      rotateAboutRoot(this.root, this.hips, Y_AXIS, -this.hipYaw);
      rotateAboutRoot(this.root, this.spine, Y_AXIS, this.hipYaw);
    }
    const pitch = clamp(pose.pitch ?? 0, -1.1, 1.1);
    if (pitch !== 0 && this.neck && this.head) {
      rotateAboutRoot(this.root, this.neck, X_AXIS, pitch * 0.4);
      rotateAboutRoot(this.root, this.head, X_AXIS, pitch * 0.6);
    }
    this.head?.scale.setScalar(this.headless ? 1e-3 : 1);
    this.sip += ((pose.drinking ? 1 : 0) - this.sip) * (1 - Math.exp(-dt * 8));
    if (this.canteen) this.canteen.visible = this.held === 'canteen' && !pose.ride;
    if (this.canteen?.visible) this.holdCanteen(this.canteen, !pose.grounded || !!pose.sliding || !!pose.powerSlide);
    if (pose.ride) return this.ride(pose.ride);
    // Plant the feet: lock while the clip has them down (not when sliding: the sand moves with you).
    const clip = this.current?.getClip().name ?? '';
    const lock = pose.grounded && !pose.sliding && !pose.powerSlide && pose.plant !== false ? (this.minAnkle.get(clip) ?? null) : null;
    this.legIk?.update(dt, pose.grounded, lock, pose.ground ?? null);
  }

  /** Place the canteen (carried, or at the mouth while drinking) and reach the right hand to it; `loose` (in
   *  the air, sliding) leaves the arm to the clip and the canteen follows the hand. */
  private holdCanteen(can: THREE.Object3D, loose: boolean) {
    const arm = this.arms[1];
    if (!arm) return;
    this.root.updateMatrixWorld(true);
    if (loose) {
      this.root.worldToLocal(arm[2].getWorldPosition(can.position));
      can.position.y -= GRIP_UP;
      can.rotation.set(0, 0, 0);
      return;
    }
    const tip = CARRY_TIP + (DRINK_TIP - CARRY_TIP) * this.sip;
    can.rotation.set(tip, 0, 0);
    _t.copy(CARRY_AT);
    if (this.sip > 1e-3 && this.head) {
      // Neck at the mouth: bottom = mouth - (rotated up axis × height).
      this.root.worldToLocal(_p.copy(MOUTH).applyMatrix4(this.head.matrixWorld));
      _p.y -= Math.cos(tip) * CANTEEN_HEIGHT;
      _p.z -= Math.sin(tip) * CANTEEN_HEIGHT;
      _t.lerp(_p, this.sip);
    }
    can.position.copy(_t);
    // Fist round the middle, a little to the outside; elbow out and back.
    _t.x += 0.05;
    _t.y += Math.cos(tip) * GRIP_UP;
    _t.z += Math.sin(tip) * GRIP_UP;
    this.root.localToWorld(_t);
    reach(arm[0], arm[1], arm[2], _t, _pole.set(0.6, -0.5, 0.6).transformDirection(this.root.matrixWorld));
  }

  /** Sit on the bike: move the body so the hips are on the seat, bend the upper body, then reach the hands and feet. */
  private ride(r: RidePose) {
    if (!this.hips || !this.spine) return;
    this.tilt.rotation.set(0, 0, 0);
    this.root.updateMatrixWorld(true);
    this.tilt.position.add(_t.copy(r.seat).sub(this.root.worldToLocal(this.hips.getWorldPosition(_p))));
    this.root.updateMatrixWorld(true);
    rotateAboutRoot(this.root, this.spine, Z_AXIS, r.lean);
    rotateAboutRoot(this.root, this.spine, Y_AXIS, r.twist);
    rotateAboutRoot(this.root, this.spine, X_AXIS, -r.tuck);
    // Keep looking ahead over the bars.
    if (this.neck) rotateAboutRoot(this.root, this.neck, X_AXIS, r.tuck * 0.8);
    this.root.updateMatrixWorld(true);
    for (let i = 0; i < 2; i++) {
      const side = i === 0 ? -1 : 1;
      const arm = this.arms[i];
      if (arm) {
        // Wrist a hand's width behind and above the grip; elbows out and down; fingers forward round the bar.
        this.root.localToWorld(_t.copy(r.grips[i]).add(_o.set(-side * 0.02, 0.04, 0.07)));
        reach(arm[0], arm[1], arm[2], _t, _pole.set(side, -0.6, 0.4).transformDirection(this.root.matrixWorld));
        aim(arm[2], arm[3], this.root.localToWorld(_t.copy(r.grips[i]).add(_o.set(0, -0.03, -0.05))));
      }
      const leg = this.legs[i];
      if (leg) {
        // Knees forward and a little out, toes forward and down off the peg.
        this.root.localToWorld(_t.copy(r.pegs[i]));
        reach(leg[0], leg[1], leg[2], _t, _pole.set(side * 0.35, 0.3, -1).transformDirection(this.root.matrixWorld));
        aim(leg[2], leg[3], this.root.localToWorld(_t.copy(r.pegs[i]).add(_o.set(0, -0.12, -0.12))));
      }
    }
  }

  dispose() {
    this.disposed = true;
    this.mixer?.stopAllAction();
    this.mixer?.uncacheRoot(this.mixer.getRoot());
    for (const m of this.tint) m.dispose();
    this.root.removeFromParent();
  }
}

function isLocomotion(a: THREE.AnimationAction) {
  const n = a.getClip().name;
  return n === 'Walk' || n === 'Run' || n === 'CrouchWalk';
}

function clamp(x: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, x));
}

const _axis = new THREE.Vector3();
const _q = new THREE.Quaternion();
const _qa = new THREE.Quaternion();

const X_AXIS = new THREE.Vector3(1, 0, 0);
const Y_AXIS = new THREE.Vector3(0, 1, 0);
const Z_AXIS = new THREE.Vector3(0, 0, 1);
const _t = new THREE.Vector3();
const _p = new THREE.Vector3();
const _o = new THREE.Vector3();
const _pole = new THREE.Vector3();
const _s = new THREE.Vector3();
const _e = new THREE.Vector3();
const _w = new THREE.Vector3();
const _dir = new THREE.Vector3();
const _bend = new THREE.Vector3();
const _from = new THREE.Vector3();
const _wq = new THREE.Quaternion();
const _pq = new THREE.Quaternion();

/** Two-bone IK: turn `upper` and `lower` so `end` (the lower bone's child) reaches `target`, the middle joint
 *  bending towards `pole` (world directions and points). */
function reach(upper: THREE.Object3D, lower: THREE.Object3D, end: THREE.Object3D, target: THREE.Vector3, pole: THREE.Vector3) {
  upper.getWorldPosition(_s);
  lower.getWorldPosition(_e);
  end.getWorldPosition(_w);
  const a = _s.distanceTo(_e), b = _e.distanceTo(_w);
  _dir.subVectors(target, _s);
  const d = clamp(_dir.length(), Math.abs(a - b) + 1e-3, a + b - 1e-3);
  _dir.normalize();
  const along = (a * a - b * b + d * d) / (2 * d);
  _bend.copy(pole).addScaledVector(_dir, -pole.dot(_dir)).normalize();
  _e.copy(_s).addScaledVector(_dir, along).addScaledVector(_bend, Math.sqrt(Math.max(0, a * a - along * along)));
  aim(upper, lower, _e);
  aim(lower, end, target);
}

/** Turn `bone` (the shortest way) so its child `child` lies on the line towards `target` (world). */
function aim(bone: THREE.Object3D, child: THREE.Object3D, target: THREE.Vector3) {
  bone.getWorldPosition(_p);
  _from.subVectors(child.getWorldPosition(_w), _p).normalize();
  _q.setFromUnitVectors(_from, _w.subVectors(target, _p).normalize());
  bone.getWorldQuaternion(_wq);
  bone.parent!.getWorldQuaternion(_pq);
  bone.quaternion.copy(_pq.invert().multiply(_q).multiply(_wq));
  bone.updateMatrixWorld(true);
}

/** Rotate `bone` by `angle` about one of the root's local axes (about X, + = look up for a model facing -Z). */
function rotateAboutRoot(root: THREE.Object3D, bone: THREE.Object3D, axis: THREE.Vector3, angle: number) {
  _axis.copy(axis).transformDirection(root.matrixWorld);
  bone.getWorldQuaternion(_q);
  _axis.applyQuaternion(_q.invert());
  bone.quaternion.multiply(_qa.setFromAxisAngle(_axis, angle));
}
